"""Public NFL accuracy scorecard and filterable frozen-forecast results."""
import html,json
from pathlib import Path
import seo
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'data/nfl_weekly/2026/week-1/results.json'
def load():return json.loads(SOURCE.read_text())
def scorecard():
    r=load();s=r['summary']['half_ppr']['top30']
    positions=' · '.join(f'{p} {v["mae"]:.1f}' for p,v in r['summary']['half_ppr']['positions'].items())
    summary=json.dumps(r['summary'],separators=(',',':'))
    return f'''<section class="wb-up-next" aria-label="Week 1 projection accuracy"><div><div class="wb-score-label">The weekly scorecard · NFL Week 1</div><h2><span id="accuracy-mae">{s['mae']:.1f}</span> points average miss</h2><p id="accuracy-detail">Half-PPR · {s['matched']}/120 graded · Top 30 per position</p><p id="accuracy-positions">{positions}</p><p>Frozen before kickoff. Missing stat lines stay ungraded.</p><a href="/nfl/week-1/results/">See projected vs. actual →</a></div><span class="wb-pending">WEEK 1 RESULTS</span></section><script>document.addEventListener('DOMContentLoaded',()=>{{const s={summary},f=document.getElementById('wb-format');if(!f)return;function u(){{let x=s[f.value],labels={{half_ppr:'Half-PPR',ppr:'PPR',non_ppr:'Non-PPR'}};document.getElementById('accuracy-mae').textContent=x.top30.mae.toFixed(1);document.getElementById('accuracy-detail').textContent=labels[f.value]+' · '+x.top30.matched+'/120 graded · Top 30 per position';document.getElementById('accuracy-positions').textContent=Object.entries(x.positions).map(([p,v])=>p+' '+v.mae.toFixed(1)).join(' · ');}}f.addEventListener('change',u);u();}});</script>'''

def build_results(site):
    from build_nfl_week1_boards import CSS
    r=load();e=lambda s:html.escape(str(s),quote=True)
    rows=[]
    for p in sorted(r['rows'],key=lambda p:(p['position'],p['formats']['half_ppr']['rank'])):
        f=p['formats']['half_ppr']
        rows.append(f'<tr data-id="{e(p["id"])}"><td class="player">{e(p["name"])}<small>{e(p["team"])} · {p["position"]}</small></td><td data-rank>{f["rank"]}</td><td data-proj>{f["projected"]:.1f}</td><td data-actual>{f["actual"] if f["actual"] is not None else "Ungraded"}</td><td data-error>{f["error"] if f["error"] is not None else "—"}</td></tr>')
    blob=json.dumps(r,separators=(',',':')).replace('<','\\u003c')
    js="""(()=>{const d=JSON.parse(document.getElementById('results-data').textContent),f=document.getElementById('wb-format'),pos=document.getElementById('result-position'),q=document.getElementById('result-search'),scope=document.getElementById('result-scope'),body=document.getElementById('results-rows'),rows=new Map([...body.rows].map(r=>[r.dataset.id,r]));function render(){let shown=0;for(let p of d.rows){let r=rows.get(p.id),v=p.formats[f.value];r.hidden=!!((pos.value&&p.position!==pos.value)||(scope.value==='top'&&v.rank>30)||(q.value&&!p.name.toLowerCase().includes(q.value.toLowerCase())));if(!r.hidden)shown++;r.querySelector('[data-rank]').textContent=v.rank;r.querySelector('[data-proj]').textContent=v.projected.toFixed(1);r.querySelector('[data-actual]').textContent=v.actual===null?'Ungraded':v.actual.toFixed(1);r.querySelector('[data-error]').textContent=v.error===null?'—':(v.error>0?'+':'')+v.error.toFixed(1);}document.getElementById('result-count').textContent=shown+' players shown';}for(let el of [f,pos,scope])el.addEventListener('change',render);q.addEventListener('input',render);render();})();"""
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NFL Week 1 Projection Results | LineupBeat</title><meta name="description" content="How our Week 1 NFL fantasy projections performed, with projected vs. actual points and results by position."><link rel="canonical" href="https://lineupbeat.com/nfl/week-1/results/"><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600&amp;display=swap" rel="stylesheet"><style>{CSS}</style></head><body>{seo.site_nav(None,'nfl')}<main class="wb"><header class="wb-hero"><p class="wb-eyebrow">2026 NFL · WEEK 1 RESULTS</p><h1>We show <span>our work.</span></h1><p class="wb-intro">Our pregame projections against the final results. Every hit. Every miss.</p></header><nav class="wb-links"><a href="/nfl/week-2/rankings/">Week 2 rankings</a><a href="/nfl/week-2/projections/">Week 2 projections</a><a href="/nfl/week-1/rankings/">Week 1 archive</a></nav>{scorecard()}<div class="wb-controls"><label>Scoring<select id="wb-format"><option value="half_ppr">Half-PPR</option><option value="ppr">PPR</option><option value="non_ppr">Non-PPR</option></select></label><label>Position<select id="result-position"><option value="">All positions</option><option>QB</option><option>RB</option><option>WR</option><option>TE</option></select></label><label>Players<select id="result-scope"><option value="top">Top 30 per position</option><option value="all">All forecast players</option></select></label><label>Search<input id="result-search" type="search" placeholder="Find a player"></label></div><p id="result-count" class="wb-note" role="status"></p><div class="wb-table" tabindex="0" role="region" aria-label="Projection results"><table><thead><tr><th class="player">Player</th><th>Pregame pos. rank</th><th>Projected</th><th>Actual</th><th>Actual − projected</th></tr></thead><tbody id="results-rows">{''.join(rows)}</tbody></table></div><details class="wb-footer"><summary>How we grade</summary><p class="wb-note">{e(r['methodology'])} NFL scoring: 0.04 per passing yard, 4 per passing touchdown, −2 per interception, 0.1 per rushing or receiving yard, 6 per rushing/receiving/return touchdown, −2 per lost fumble, 2 per two-point conversion, plus your selected reception scoring. Positive differences mean the player exceeded the projection.</p><p class="wb-note">{len([x for x in r['rows'] if x['matched']])} of {len(r['rows'])} total forecasts matched. The headline uses the top 30 projected players at each position; missing results can affect the sample. Player identity uses stable GSIS ID, team and opponent; original projected positions are preserved.</p><p class="wb-note">Final statistics: <a href="{r['source_url']}">nflverse · CC BY 4.0</a>. Forecasts: last repository snapshot before each game, including the earlier Wednesday-opener snapshot.</p></details></main>{seo.site_footer()}<script id="results-data" type="application/json">{blob}</script><script>{js}</script></body></html>'''
    out=site/'nfl/week-1/results/index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(seo.check_page(doc,'/nfl/week-1/results/'))
